"""Core query behaviour: API shape, tables, typing, names, syntax, ordering."""
import unittest

import minisql

from tests.support import DATA_DIR, MiniSQLTestCase, typed


class SpecExampleTests(MiniSQLTestCase):
    def test_spec_example(self):
        result = minisql.run(
            "SELECT name, price FROM products WHERE price > 10 "
            "ORDER BY price DESC",
            DATA_DIR,
        )
        self.assertEqual(list(result.columns), ["name", "price"])
        self.assertEqual(typed(result.rows),
                         typed([("widget", 25), ("gadget", 12.5)]))

    def test_result_shape(self):
        result = self.run_sql("SELECT g, x FROM nums")
        self.assertIsInstance(result.columns, list)
        for c in result.columns:
            self.assertIsInstance(c, str)
        self.assertIsInstance(result.rows, list)
        for r in result.rows:
            self.assertIsInstance(r, tuple)

    def test_query_error_is_exception(self):
        self.assertTrue(issubclass(minisql.QueryError, Exception))


class TableTests(MiniSQLTestCase):
    def test_missing_table_is_error(self):
        self.assertQueryError("SELECT * FROM nope")

    def test_star_selects_all_columns_in_file_order(self):
        self.assertRows("SELECT * FROM nums",
                        [("b", 2, None), ("a", 1, 1.5), ("b", 4, None),
                         ("a", None, 2.5), ("c", None, None)],
                        columns=["g", "x", "y"])

    def test_star_uses_header_spelling(self):
        self.assertColumns("SELECT * FROM mixed",
                           ["Name", "unit price", "from", "order", 'a"b',
                            "_id", "col2"])

    def test_empty_table(self):
        self.assertRows("SELECT * FROM empty", [], columns=["id", "x"])

    def test_quoted_table_name(self):
        self.assertRows('SELECT k FROM "my table"', [(1,), (2,)])

    def test_no_order_keeps_file_order(self):
        self.assertRows("SELECT id FROM sales",
                        [(1,), (2,), (3,), (4,), (5,), (6,)])


class ValueTypingTests(MiniSQLTestCase):
    def value_for(self, ident):
        result = self.run_sql("SELECT v FROM typed WHERE id = %d" % ident)
        self.assertEqual(len(result.rows), 1)
        return result.rows[0][0]

    def check(self, ident, expected):
        self.assertEqual(typed(self.value_for(ident)), typed(expected),
                         "typed.csv id %d" % ident)

    def test_negative_integer(self):
        self.check(1, -5)

    def test_plain_integer(self):
        self.check(19, 42)

    def test_integer_with_leading_zeros(self):
        self.check(8, 7)

    def test_negative_zero_integer(self):
        self.check(18, 0)

    def test_leading_dot_decimal(self):
        self.check(2, 0.5)

    def test_trailing_dot_decimal(self):
        self.check(3, 5.0)

    def test_negative_trailing_dot_decimal(self):
        self.check(20, -7.0)

    def test_negative_leading_dot_decimal(self):
        self.check(9, -0.5)

    def test_decimal(self):
        self.check(12, 3.25)

    def test_exponent_is_string(self):
        self.check(4, "1e3")

    def test_leading_space_is_string(self):
        self.check(5, " 5")

    def test_trailing_space_is_string(self):
        self.check(13, "5 ")

    def test_plus_sign_is_string(self):
        self.check(6, "+5")

    def test_lone_minus_is_string(self):
        self.check(7, "-")

    def test_lone_dot_is_string(self):
        self.check(14, ".")

    def test_two_dots_is_string(self):
        self.check(15, "1.2.3")

    def test_empty_is_null(self):
        self.check(10, None)

    def test_words_are_strings(self):
        self.check(11, "abc")
        self.check(16, "TRUE")
        self.check(17, "NULL")

    def test_header_row_not_data(self):
        self.assertEqual(len(self.run_sql("SELECT * FROM typed").rows), 20)


class ColumnNamingTests(MiniSQLTestCase):
    def test_plain_column(self):
        self.assertColumns("SELECT x FROM nums", ["x"])

    def test_plain_column_uses_header_spelling(self):
        self.assertColumns("SELECT name FROM mixed", ["Name"])
        self.assertColumns("SELECT NAME FROM mixed", ["Name"])
        self.assertColumns("SELECT X, G FROM nums", ["x", "g"])

    def test_column_match_case_insensitive(self):
        self.assertRows("SELECT nAmE, COL2, _ID FROM mixed",
                        [("Widget", 2, 1)])

    def test_as_alias(self):
        self.assertColumns("SELECT x AS total FROM nums", ["total"])

    def test_bare_alias(self):
        self.assertColumns("SELECT x total FROM nums", ["total"])

    def test_alias_spelling_preserved(self):
        self.assertColumns("SELECT x AS Total FROM nums", ["Total"])

    def test_quoted_alias(self):
        self.assertColumns('SELECT x AS "my total" FROM nums', ["my total"])
        self.assertColumns('SELECT x "my total" FROM nums', ["my total"])

    def test_quoted_alias_with_escaped_quote(self):
        self.assertColumns('SELECT x AS "a""b" FROM nums', ['a"b'])

    def test_alias_on_expression(self):
        self.assertRows("SELECT x * 2 AS dbl FROM nums WHERE g = 'b'",
                        [(4,), (8,)], columns=["dbl"])

    def test_expression_text_as_written(self):
        self.assertColumns("SELECT x * 2 FROM nums", ["x * 2"])
        self.assertColumns("SELECT x*2 FROM nums", ["x*2"])
        self.assertColumns("SELECT x  *  2 FROM nums", ["x  *  2"])
        self.assertColumns("SELECT X + 1 FROM nums", ["X + 1"])

    def test_count_star_name(self):
        self.assertColumns("SELECT COUNT(*) FROM nums", ["COUNT(*)"])
        self.assertColumns("SELECT count(*) FROM nums", ["count(*)"])
        self.assertColumns("SELECT COUNT( * ) FROM nums", ["COUNT( * )"])

    def test_function_and_literal_names(self):
        self.assertColumns("SELECT UPPER(g), 1, 'it''s', -x FROM nums",
                           ["UPPER(g)", "1", "'it''s'", "-x"])

    def test_multiple_columns(self):
        self.assertColumns("SELECT g, x AS n, x + 1 FROM nums",
                           ["g", "n", "x + 1"])

    def test_duplicate_columns_allowed(self):
        self.assertRows("SELECT x, x FROM nums WHERE g = 'b'",
                        [(2, 2), (4, 4)], columns=["x", "x"])


class NameTests(MiniSQLTestCase):
    def test_quoted_name_with_space(self):
        self.assertRows('SELECT "unit price" FROM mixed', [(3,)],
                        columns=["unit price"])

    def test_quoted_name_with_escaped_quote(self):
        self.assertRows('SELECT "a""b" FROM mixed', [("q",)], columns=['a"b'])

    def test_quoted_keyword_names(self):
        self.assertRows('SELECT "from", "order" FROM mixed', [("f", "o")],
                        columns=["from", "order"])

    def test_quoted_plain_name(self):
        self.assertRows('SELECT "Name" FROM mixed', [("Widget",)],
                        columns=["Name"])

    def test_underscore_and_digits(self):
        self.assertRows("SELECT _id, col2 FROM mixed", [(1, 2)])

    def test_keywords_not_usable_as_unquoted_names(self):
        self.assertQueryError("SELECT from FROM mixed")
        self.assertQueryError("SELECT order FROM mixed")
        self.assertQueryError("SELECT x AS select FROM nums")
        self.assertQueryError("SELECT x AS from FROM nums")
        self.assertQueryError("SELECT x AS where FROM nums")
        self.assertQueryError("SELECT x FROM nums ORDER BY order")

    def test_keywords_case_insensitive(self):
        self.assertRows(
            "select g, x as n from nums where x is not null and x > 1 "
            "order by x desc limit 1 offset 0",
            [("b", 4)], columns=["g", "n"])
        self.assertRows("SeLeCt DiStInCt g FrOm nums", [("b",), ("a",), ("c",)])
        self.assertRows(
            "select x from nums where x between 1 and 2 and g like 'b' "
            "and x not in (5)", [(2,)])
        self.assertRows(
            "select region, count(*) from sales group by region "
            "having count(*) > 1 order by region asc",
            [("north", 3), ("south", 2)])


class DistinctTests(MiniSQLTestCase):
    def test_distinct_single_column(self):
        self.assertRows("SELECT DISTINCT g FROM nums", [("b",), ("a",), ("c",)])

    def test_distinct_multiple_columns(self):
        self.assertRows("SELECT DISTINCT region, product FROM sales",
                        [("north", "apple"), ("south", "pear"),
                         ("north", "pear"), ("east", "apple"),
                         ("south", "apple")])

    def test_distinct_on_expression(self):
        self.assertRows("SELECT DISTINCT price * 2 FROM sales",
                        [(3.0,), (4,)])

    def test_distinct_with_order_by(self):
        self.assertRows("SELECT DISTINCT g FROM nums ORDER BY g",
                        [("a",), ("b",), ("c",)])

    def test_distinct_with_limit(self):
        self.assertRows("SELECT DISTINCT g FROM nums LIMIT 2",
                        [("b",), ("a",)])

    def test_distinct_star(self):
        self.assertRows("SELECT DISTINCT * FROM \"my table\"", [(1,), (2,)])


class OrderByTests(MiniSQLTestCase):
    def test_ascending_default_nulls_first(self):
        self.assertRows("SELECT x FROM nums ORDER BY x",
                        [(None,), (None,), (1,), (2,), (4,)])

    def test_explicit_asc(self):
        self.assertRows("SELECT x FROM nums ORDER BY x ASC",
                        [(None,), (None,), (1,), (2,), (4,)])

    def test_descending_nulls_last(self):
        self.assertRows("SELECT x FROM nums ORDER BY x DESC",
                        [(4,), (2,), (1,), (None,), (None,)])

    def test_mixed_int_float_sort(self):
        self.assertRows("SELECT price FROM sales ORDER BY price, id",
                        [(1.5,), (1.5,), (1.5,), (1.5,), (2,), (2,)])

    def test_strings_sort_by_code_point(self):
        self.assertRows("SELECT w FROM words WHERE w IS NOT NULL ORDER BY w",
                        [("Apple",), ("a",), ("a.c",), ("abc",), ("apple",),
                         ("banana",)])

    def test_stable_ascending(self):
        self.assertRows("SELECT g, x FROM nums ORDER BY g",
                        [("a", 1), ("a", None), ("b", 2), ("b", 4),
                         ("c", None)])

    def test_stable_descending(self):
        self.assertRows("SELECT g, x FROM nums ORDER BY g DESC",
                        [("c", None), ("b", 2), ("b", 4), ("a", 1),
                         ("a", None)])

    def test_stable_nulls(self):
        # Rows with NULL x keep file order (a before c) in both directions.
        self.assertRows("SELECT g FROM nums ORDER BY x",
                        [("a",), ("c",), ("a",), ("b",), ("b",)])
        self.assertRows("SELECT g FROM nums ORDER BY x DESC",
                        [("b",), ("b",), ("a",), ("a",), ("c",)])

    def test_multiple_keys(self):
        self.assertRows("SELECT g, x FROM nums ORDER BY g DESC, x DESC",
                        [("c", None), ("b", 4), ("b", 2), ("a", 1),
                         ("a", None)])
        self.assertRows("SELECT g, x FROM nums ORDER BY g, x DESC",
                        [("a", 1), ("a", None), ("b", 4), ("b", 2),
                         ("c", None)])

    def test_order_by_output_alias(self):
        self.assertRows("SELECT x * 10 AS t FROM nums ORDER BY t DESC",
                        [(40,), (20,), (10,), (None,), (None,)])

    def test_output_alias_shadows_input_column(self):
        # x refers to the output column (-x), not the input column x.
        self.assertRows("SELECT -x AS x FROM nums ORDER BY x",
                        [(None,), (None,), (-4,), (-2,), (-1,)])

    def test_order_by_position(self):
        self.assertRows("SELECT g, x FROM nums ORDER BY 2",
                        [("a", None), ("c", None), ("a", 1), ("b", 2),
                         ("b", 4)])
        self.assertRows("SELECT g, x FROM nums ORDER BY 1 DESC, 2",
                        [("c", None), ("b", 2), ("b", 4), ("a", None),
                         ("a", 1)])

    def test_order_by_position_of_expression(self):
        self.assertRows("SELECT id, -id FROM sales ORDER BY 2 LIMIT 2",
                        [(6, -6), (5, -5)])

    def test_order_by_expression_not_in_output(self):
        self.assertRows("SELECT g FROM nums ORDER BY x DESC",
                        [("b",), ("b",), ("a",), ("a",), ("c",)])
        self.assertRows("SELECT id FROM sales ORDER BY -id LIMIT 3",
                        [(6,), (5,), (4,)])

    def test_order_by_input_column_not_selected(self):
        self.assertRows("SELECT product FROM sales ORDER BY qty",
                        [("apple",), ("apple",), ("pear",), ("apple",),
                         ("apple",), ("pear",)])

    def test_order_by_non_bare_integer_expression_is_constant(self):
        # 1 + 0 is not a bare integer, so it is an expression (a constant);
        # the stable sort keeps file order.
        self.assertRows("SELECT x, g FROM nums ORDER BY 1 + 0",
                        [(2, "b"), (1, "a"), (4, "b"), (None, "a"),
                         (None, "c")])

    def test_order_by_unknown_column_is_error(self):
        self.assertQueryError("SELECT x FROM nums ORDER BY nope")


class LimitOffsetTests(MiniSQLTestCase):
    def test_limit(self):
        self.assertRows("SELECT id FROM sales LIMIT 2", [(1,), (2,)])

    def test_limit_zero(self):
        self.assertRows("SELECT id FROM sales LIMIT 0", [])

    def test_limit_larger_than_rows(self):
        self.assertRows("SELECT k FROM \"my table\" LIMIT 10", [(1,), (2,)])

    def test_limit_offset(self):
        self.assertRows("SELECT id FROM sales LIMIT 2 OFFSET 1", [(2,), (3,)])

    def test_offset_past_end(self):
        self.assertRows("SELECT id FROM sales LIMIT 2 OFFSET 10", [])

    def test_offset_zero(self):
        self.assertRows("SELECT id FROM sales LIMIT 1 OFFSET 0", [(1,)])

    def test_limit_after_sorting(self):
        self.assertRows("SELECT x FROM nums ORDER BY x DESC LIMIT 2",
                        [(4,), (2,)])
        self.assertRows(
            "SELECT id FROM sales ORDER BY price DESC, id LIMIT 2 OFFSET 1",
            [(3,), (1,)])

    def test_offset_without_limit_is_error(self):
        self.assertQueryError("SELECT id FROM sales OFFSET 1")

    def test_limit_requires_integer(self):
        self.assertQueryError("SELECT id FROM sales LIMIT")
        self.assertQueryError("SELECT id FROM sales LIMIT 1.5")
        self.assertQueryError("SELECT id FROM sales LIMIT 'a'")
        self.assertQueryError("SELECT id FROM sales LIMIT 1 OFFSET")


class SyntaxTests(MiniSQLTestCase):
    def test_trailing_semicolon(self):
        self.assertRows("SELECT k FROM \"my table\";", [(1,), (2,)])
        self.assertRows("SELECT k FROM \"my table\" LIMIT 1 ;", [(1,)])

    def test_whitespace_and_newlines(self):
        self.assertRows("  SELECT\n  k\nFROM\t\"my table\"\n  ", [(1,), (2,)])

    def test_syntax_errors(self):
        bad = [
            "",
            "SELECT",
            "SELEC x FROM nums",
            "SELECT FROM nums",
            "SELECT x",
            "SELECT 1",
            "SELECT x FROM",
            "SELECT x, FROM nums",
            "SELECT x FROM nums WHERE",
            "SELECT x FROM nums extra",
            "SELECT x FROM nums WHERE x = = 1",
            "SELECT (x FROM nums",
            "SELECT x) FROM nums",
            "SELECT 1 + FROM nums",
            "SELECT 'abc FROM nums",
            "SELECT \"abc FROM nums",
            "SELECT x FROM nums ORDER x",
            "SELECT x FROM nums GROUP x",
            "SELECT x FROM nums ORDER BY",
            "SELECT x FROM nums; SELECT x FROM nums",
            "SELECT x FROM nums WHERE x IN 1",
            "SELECT x FROM nums WHERE x IN ()",
            "SELECT x FROM nums WHERE x BETWEEN 1",
            "SELECT x FROM nums WHERE x IS 1",
            "SELECT x # 1 FROM nums",
            "SELECT *, x FROM nums",
            "SELECT x FROM nums LIMIT 1 WHERE x > 1",
            "SELECT x FROM nums ORDER BY x WHERE x > 1",
            "SELECT x AS FROM nums",
            "SELECT LOWER('a' FROM nums",
        ]
        for sql in bad:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)


class UnknownNameTests(MiniSQLTestCase):
    def test_unknown_column_in_select(self):
        self.assertQueryError("SELECT nope FROM nums")

    def test_unknown_column_in_where(self):
        self.assertQueryError("SELECT x FROM nums WHERE nope = 1")

    def test_unknown_column_in_expression(self):
        self.assertQueryError("SELECT x + nope FROM nums")

    def test_unknown_column_on_empty_table(self):
        self.assertQueryError("SELECT nope FROM empty")

    def test_string_literal_is_not_a_column(self):
        self.assertRows("SELECT 'x' FROM \"my table\"", [("x",), ("x",)])

    def test_quoted_name_is_a_column_not_a_string(self):
        self.assertQueryError('SELECT "nope" FROM nums')


if __name__ == "__main__":
    unittest.main()

