"""Aggregates, GROUP BY, HAVING."""
import unittest

from tests.support import MiniSQLTestCase


class AggregateTests(MiniSQLTestCase):
    def test_count_star_and_count_expr(self):
        self.assertRows("SELECT COUNT(*), COUNT(x), COUNT(y), COUNT(g) "
                        "FROM nums", [(5, 3, 2, 5)])

    def test_sum_of_integers_is_int(self):
        self.assertRows("SELECT SUM(x) FROM nums", [(7,)])

    def test_sum_of_floats_is_float(self):
        self.assertRows("SELECT SUM(y) FROM nums", [(4.0,)])

    def test_sum_mixed_int_float(self):
        self.assertRows("SELECT SUM(price) FROM sales WHERE region = 'south'",
                        [(3.5,)])

    def test_avg_is_always_float(self):
        self.assertRows("SELECT AVG(x) FROM nums WHERE g = 'b'", [(3.0,)])
        self.assertRows("SELECT AVG(x) FROM nums", [(7 / 3,)])
        self.assertRows("SELECT AVG(y) FROM nums", [(2.0,)])

    def test_min_max_ignore_nulls(self):
        self.assertRows("SELECT MIN(x), MAX(x), MIN(y), MAX(y) FROM nums",
                        [(1, 4, 1.5, 2.5)])

    def test_min_max_strings(self):
        self.assertRows("SELECT MIN(g), MAX(g) FROM nums", [("a", "c")])

    def test_aggregates_on_expressions(self):
        self.assertRows("SELECT SUM(x * 2), MAX(-x), COUNT(x + 1) FROM nums",
                        [(14, -1, 3)])

    def test_expressions_of_aggregates(self):
        self.assertRows("SELECT SUM(x) + 1, COUNT(*) * 2, SUM(x) / COUNT(x) "
                        "FROM nums", [(8, 10, 7 / 3)])

    def test_aggregate_names_case_insensitive(self):
        self.assertRows("SELECT count(*), sum(x), avg(x), min(x), max(x) "
                        "FROM nums WHERE g = 'b'", [(2, 6, 3.0, 2, 4)])

    def test_aggregates_on_empty_input(self):
        self.assertRows("SELECT COUNT(*), COUNT(x), SUM(x), AVG(x), MIN(x), "
                        "MAX(x) FROM nums WHERE FALSE",
                        [(0, 0, None, None, None, None)])

    def test_aggregates_on_empty_table(self):
        self.assertRows("SELECT COUNT(*), SUM(x) FROM empty", [(0, None)])

    def test_aggregates_all_null(self):
        self.assertRows("SELECT COUNT(*), COUNT(x), SUM(x), AVG(x), MIN(x), "
                        "MAX(x) FROM nums WHERE g = 'c'",
                        [(1, 0, None, None, None, None)])

    def test_global_count_where_false_spec_example(self):
        self.assertRows("SELECT COUNT(*) FROM nums WHERE FALSE", [(0,)],
                        columns=["COUNT(*)"])

    def test_global_aggregate_with_literal(self):
        self.assertRows("SELECT 'n', COUNT(*) FROM nums", [("n", 5)])

    def test_aggregate_names(self):
        self.assertColumns("SELECT COUNT(x), SUM(x), avg(x) FROM nums",
                           ["COUNT(x)", "SUM(x)", "avg(x)"])

    def test_aggregate_in_where_is_error(self):
        self.assertQueryError("SELECT g FROM nums WHERE COUNT(*) > 1")
        self.assertQueryError("SELECT g FROM nums WHERE SUM(x) > 1")

    def test_nested_aggregates_are_error(self):
        self.assertQueryError("SELECT SUM(COUNT(*)) FROM nums")
        self.assertQueryError("SELECT MAX(SUM(x)) FROM nums GROUP BY g")
        self.assertQueryError("SELECT SUM(x + COUNT(*)) FROM nums")


class GroupByTests(MiniSQLTestCase):
    def test_groups_in_first_row_order(self):
        self.assertRows("SELECT g, COUNT(*) FROM nums GROUP BY g",
                        [("b", 2), ("a", 2), ("c", 1)],
                        columns=["g", "COUNT(*)"])

    def test_all_aggregates_per_group(self):
        self.assertRows(
            "SELECT region, SUM(qty), AVG(qty), MIN(qty), MAX(qty), "
            "COUNT(qty), COUNT(*) FROM sales GROUP BY region",
            [("north", 6, 2.0, 1, 3, 3, 3),
