        self.assertRows("SELECT region, SUM(price) FROM sales GROUP BY region",
                        [("north", 5.0), ("south", 3.5), ("east", 1.5)])

    def test_group_without_aggregate(self):
        self.assertRows("SELECT region FROM sales GROUP BY region",
                        [("north",), ("south",), ("east",)])

    def test_group_column_not_selected(self):
        self.assertRows("SELECT COUNT(*) FROM sales GROUP BY region",
                        [(3,), (2,), (1,)])

    def test_group_by_multiple_expressions(self):
        self.assertRows(
            "SELECT g, x IS NULL, COUNT(*) FROM nums GROUP BY g, x IS NULL",
            [("b", False, 2), ("a", False, 1), ("a", True, 1),
             ("c", True, 1)])

    def test_group_by_expression_reused_in_select(self):
        self.assertRows(
            "SELECT price * 2 AS p2, COUNT(*) FROM sales GROUP BY price * 2",
            [(3.0, 4), (4, 2)], columns=["p2", "COUNT(*)"])

    def test_group_by_expression_name(self):
        self.assertColumns(
            "SELECT price * 2, COUNT(*) FROM sales GROUP BY price * 2",
            ["price * 2", "COUNT(*)"])

    def test_group_expression_inside_larger_expression(self):
        self.assertRows("SELECT region || '!' FROM sales GROUP BY region",
                        [("north!",), ("south!",), ("east!",)])

    def test_group_by_column_case_insensitive(self):
        self.assertRows("SELECT REGION, COUNT(*) FROM sales GROUP BY region",
                        [("north", 3), ("south", 2), ("east", 1)])

    def test_group_by_on_empty_input_gives_no_rows(self):
        self.assertRows("SELECT g, COUNT(*) FROM nums WHERE FALSE GROUP BY g",
                        [])
        self.assertRows("SELECT x, COUNT(*) FROM empty GROUP BY x", [])

    def test_where_applies_before_grouping(self):
        self.assertRows("SELECT region, COUNT(*) FROM sales WHERE qty > 1 "
                        "GROUP BY region",
                        [("north", 2), ("south", 2)])

    def test_non_grouped_column_is_error(self):
        self.assertQueryError("SELECT g, x FROM nums GROUP BY g")
        self.assertQueryError("SELECT x FROM nums GROUP BY g")
        self.assertQueryError("SELECT product, COUNT(*) FROM sales "
                              "GROUP BY region")

    def test_column_with_aggregate_without_group_by_is_error(self):
        self.assertQueryError("SELECT x, COUNT(*) FROM nums")
        self.assertQueryError("SELECT g, SUM(x) FROM nums")

    def test_non_grouped_column_in_having_is_error(self):
        self.assertQueryError("SELECT g FROM nums GROUP BY g HAVING x > 1")


class HavingTests(MiniSQLTestCase):
    def test_having_aggregate(self):
        self.assertRows("SELECT g, SUM(x) FROM nums GROUP BY g "
                        "HAVING SUM(x) > 2", [("b", 6)])

    def test_having_drops_null(self):
        # Group c has SUM(x) NULL, so the condition is NULL and it is dropped.
        self.assertRows("SELECT g FROM nums GROUP BY g HAVING SUM(x) < 100",
                        [("b",), ("a",)])

    def test_having_count(self):
        self.assertRows("SELECT region FROM sales GROUP BY region "
                        "HAVING COUNT(*) >= 2", [("north",), ("south",)])

    def test_having_group_column(self):
        self.assertRows("SELECT g, COUNT(*) FROM nums GROUP BY g "
                        "HAVING g = 'a'", [("a", 2)])

    def test_having_aggregate_not_selected(self):
        self.assertRows("SELECT region FROM sales GROUP BY region "
                        "HAVING MAX(qty) = 5", [("south",)])

    def test_having_without_group_by(self):
        self.assertRows("SELECT COUNT(*) FROM nums HAVING COUNT(*) > 10", [])
        self.assertRows("SELECT COUNT(*) FROM nums HAVING COUNT(*) = 5",
                        [(5,)])

    def test_aggregate_in_having_makes_query_grouped(self):
        self.assertRows("SELECT 'x' FROM nums HAVING COUNT(*) = 5", [("x",)])
        self.assertQueryError("SELECT g FROM nums HAVING COUNT(*) > 0")


class GroupedOrderTests(MiniSQLTestCase):
    def test_order_by_aggregate(self):
        self.assertRows("SELECT g, SUM(x) FROM nums GROUP BY g "
                        "ORDER BY SUM(x) DESC",
                        [("b", 6), ("a", 1), ("c", None)])

    def test_order_by_aggregate_ascending_nulls_first(self):
        self.assertRows("SELECT g, SUM(x) FROM nums GROUP BY g "
                        "ORDER BY SUM(x)",
                        [("c", None), ("a", 1), ("b", 6)])

    def test_order_by_aggregate_not_selected_stable(self):
        # counts: b 2, a 2, c 1 -> c first, then b and a keep group order
        self.assertRows("SELECT g FROM nums GROUP BY g ORDER BY COUNT(*)",
                        [("c",), ("b",), ("a",)])

    def test_order_by_alias_of_aggregate(self):
        self.assertRows("SELECT region, SUM(qty) AS total FROM sales "
                        "GROUP BY region ORDER BY total DESC",
                        [("south", 9), ("north", 6), ("east", None)])

    def test_order_by_position_grouped(self):
        self.assertRows("SELECT region, COUNT(*) FROM sales GROUP BY region "
                        "ORDER BY 2, 1",
                        [("east", 1), ("south", 2), ("north", 3)])

    def test_order_by_group_column(self):
        self.assertRows("SELECT COUNT(*) FROM sales GROUP BY region "
                        "ORDER BY region",
                        [(1,), (3,), (2,)])

    def test_aggregate_in_order_by_makes_query_grouped(self):
        self.assertRows("SELECT 'x' FROM nums ORDER BY COUNT(*)", [("x",)])
        self.assertQueryError("SELECT x FROM nums ORDER BY COUNT(*)")

    def test_grouped_limit(self):
        self.assertRows("SELECT region FROM sales GROUP BY region "
                        "ORDER BY region LIMIT 1 OFFSET 1", [("north",)])


if __name__ == "__main__":
    unittest.main()

